    """Complete a grid masked in patches, using its horizontal and vertical mirror symmetry."""
    h, w = len(grid), len(grid[0])
    if h % 2 or w % 2:
        raise ValueError("expected even dimensions with central mirror axes")
    out = [row[:] for row in grid]
    changed = True
    while changed:
        changed = False
        for r in range(h):
            for c in range(w):
                if out[r][c] != 2:
                    continue
                partners = [(r, w - 1 - c), (h - 1 - r, c)]
                known = [out[rr][cc] for rr, cc in partners if out[rr][cc] != 2]
                if known:
                    if any(v != known[0] for v in known):
                        raise ValueError(f"mirror disagreement at {(r, c)}: {known}")
                    out[r][c] = known[0]
                    changed = True
    if any(v == 2 for row in out for v in row):
        raise ValueError("masked cells are not recoverable by mirror symmetry")
    # Verify both symmetries on the completed grid.
    for r in range(h):
        for c in range(w):
            if out[r][c] != out[r][w - 1 - c] or out[r][c] != out[h - 1 - r][c]:
                raise ValueError(f"completed grid violates mirror symmetry at {(r, c)}")
    return out
